if (owner.stabbing) 
{ 
    shot = instance_create(x,y,StabMask);
    shot.direction=stabdirection;
    shot.speed=0;
    shot.owner=owner;
    shot.ownerPlayer=ownerPlayer;
    shot.team=owner.team;
    if ((owner.weapons[1] == WEAPON_ZAPPER || owner.weapons[0] == WEAPON_ZAPPER) and weaponType != WTYPE_MELEE_STAB) // correcting for randomizerMode
    {
        shot.hitDamage = smashDamage*2;
        shot.weapon = damSource;
    } else {
        shot.hitDamage = 200;
        shot.weapon=DAMAGE_SOURCE_KNIFE;
    }
}
